

from sqlalchemy import Column, Integer, String, DateTime
from sqlalchemy.sql import func
from sqlalchemy.orm import relationship

from app.core.database import Base


class Session(Base):
    __tablename__ = "sessions"

    # Unique ID generated by PostgreSQL
    id = Column(Integer, primary_key=True, index=True)

    # Optional name for the camera session
    session_name = Column(String(100), nullable=True)

    # Current session status: active or ended
    status = Column(String(20), default="active", nullable=False)

    # Session creation timestamp
    created_at = Column(
        DateTime(timezone=True),
        server_default=func.now(),
        nullable=False
    )

    # Session ending timestamp
    ended_at = Column(
        DateTime(timezone=True),
        nullable=True
    )

    # All frames captured during this session
    frames = relationship(
        "Frame",
        back_populates="session",
        cascade="all, delete-orphan"
    )
